const latestControlRuns = `-- name: LatestControlRuns :many
SELECT DISTINCT ON (r.control, r.frequency, r.check_how) r.organisation_id, r.id, r.control, r.frequency, r.check_how, r.since, r.ran_at, r.ok, r.item_count, r.items, r.detail
  FROM fyniq.control_run r
 ORDER BY r.control, r.frequency, r.check_how, r.ran_at DESC, r.id DESC
`

// The latest run of each verification of each control.
func (q *Queries) LatestControlRuns(ctx context.Context) ([]FyniqControlRun, error) {
	rows, err := q.db.Query(ctx, latestControlRuns)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []FyniqControlRun
	for rows.Next() {
		var i FyniqControlRun
		if err := rows.Scan(
			&i.OrganisationID,
			&i.ID,
			&i.Control,
			&i.Frequency,
			&i.CheckHow,
			&i.Since,
			&i.RanAt,
			&i.Ok,
			&i.ItemCount,
			&i.Items,
			&i.Detail,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

