const nextRiskRef = `-- name: NextRiskRef :one
SELECT ('R' || (coalesce(max(substring(r.ref FROM 2)::integer), 0) + 1))::text AS ref FROM fyniq.risk r
`

// The next reference of a new risk: R and one more than the highest number used.
func (q *Queries) NextRiskRef(ctx context.Context) (string, error) {
	row := q.db.QueryRow(ctx, nextRiskRef)
	var ref string
	err := row.Scan(&ref)
	return ref, err
}

const updateControlState = `-- name: UpdateControlState :one
UPDATE fyniq.control_state
   SET status = $1, detail = $2, checks = $3, failing_since = $4,
       run_at = $5, changed_at = $6, version = version + 1
 WHERE control = $7 AND version = $8
RETURNING organisation_id, id, control, status, detail, checks, failing_since, run_at, changed_at, version
`

type UpdateControlStateParams struct {
	Status       string
	Detail       string
	Checks       []byte
	FailingSince *time.Time
	RunAt        time.Time
	ChangedAt    time.Time
	Control      string
	Version      int32
}

func (q *Queries) UpdateControlState(ctx context.Context, arg UpdateControlStateParams) (FyniqControlState, error) {
	row := q.db.QueryRow(ctx, updateControlState,
		arg.Status,
		arg.Detail,
		arg.Checks,
		arg.FailingSince,
		arg.RunAt,
		arg.ChangedAt,
		arg.Control,
		arg.Version,
	)
	var i FyniqControlState
	err := row.Scan(
		&i.OrganisationID,
		&i.ID,
		&i.Control,
		&i.Status,
		&i.Detail,
		&i.Checks,
		&i.FailingSince,
		&i.RunAt,
		&i.ChangedAt,
		&i.Version,
	)
	return i, err
}
